	public static function cron_schedules($s){if(!isset($s['gcu_five_minutes'])){$s['gcu_five_minutes']=array('interval'=>300,'display'=>__('Every five minutes (File 14)','global-clinic-usp-integration'));}return $s;}
	public static function activate(){$r=self::install_or_upgrade(true);if(is_wp_error($r)){update_option(self::UPGRADE_ERROR,self::safe_error_record($r),false);update_option('gcu_enabled',0,false);wp_die(esc_html($r->get_error_message()));}$future=self::ensure_future_schema(true);if(is_wp_error($future)){update_option(self::UPGRADE_ERROR,self::safe_error_record($future),false);update_option('gcu_enabled',0,false);wp_die(esc_html($future->get_error_message()));}}
	public static function deactivate(){foreach(array('gcu_daily_governance_check','gcu_process_outbox','gcu_process_inbox','gcu_lifecycle_cleanup','gcu_future_daily_governance','gcu_future_hourly_intelligence')as$h){wp_clear_scheduled_hook($h);}flush_rewrite_rules();}
	public static function safe_repair(){
		$result=self::install_or_upgrade(false);
		if(is_wp_error($result)){return $result;}
		return self::ensure_future_schema(true);
	}
	public static function maybe_upgrade(){if(GCU_VERSION===(string)get_option(self::VERSION_OPTION,'')&&GCU_SCHEMA_VERSION===(int)get_option(self::SCHEMA_OPTION,0)){$future=self::ensure_future_schema();if(is_wp_error($future)){update_option(self::UPGRADE_ERROR,self::safe_error_record($future),false);return$future;}return true;}$r=self::install_or_upgrade(false);if(is_wp_error($r)){update_option(self::UPGRADE_ERROR,self::safe_error_record($r),false);update_option('gcu_enabled',0,false);return$r;}$future=self::ensure_future_schema(true);if(is_wp_error($future)){update_option(self::UPGRADE_ERROR,self::safe_error_record($future),false);return$future;}return true;}
	private static function ensure_future_schema($force_verify=false){if(!class_exists('GCU_Future_Intelligence')){return true;}$r=GCU_Future_Intelligence::ensure_schema($force_verify);if(is_wp_error($r)){update_option(GCU_Future_Intelligence::SAFE_MODE_OPTION,1,false);GCU_Observability::log('error','future_schema_upgrade_deferred',array('code'=>$r->get_error_code()));}return$r;}
	public static function ready_for_runtime(){if(self::install_lock_active()){return new WP_Error('gcu_install_in_progress',__('File 14 install, upgrade or recovery is in progress.','global-clinic-usp-integration'),array('status'=>503));}if(!get_option('gcu_enabled',1)){return new WP_Error('gcu_safe_mode',__('File 14 is in safe mode.','global-clinic-usp-integration'),array('status'=>503));}if(GCU_VERSION!==(string)get_option(self::VERSION_OPTION,'')||GCU_SCHEMA_VERSION!==(int)get_option(self::SCHEMA_OPTION,0)){return new WP_Error('gcu_upgrade_pending',__('File 14 requires a verified schema upgrade before runtime can continue.','global-clinic-usp-integration'),array('status'=>503));}return true;}public static function ready_for_mutation(){return self::ready_for_runtime();}
	private static function install_or_upgrade($activation){if(!self::acquire_lock()){return new WP_Error('gcu_install_locked',__('Global Clinic USP installation or upgrade is already running. Please retry shortly.','global-clinic-usp-integration'));}try{$keys=GCU_Integrity::ensure_keys();if(is_wp_error($keys)){return $keys;}$snap=self::capture_snapshot(true);if(is_wp_error($snap)){return $snap;}$schema=self::schema();if(is_wp_error($schema)){return $schema;}GCU_Capabilities::install();$seed=self::seed_governed_content();if(is_wp_error($seed)){return $seed;}$migration=self::migrate_legacy();if(is_wp_error($migration)){return $migration;}$integrity=GCU_Integrity::migrate_legacy_hashes();if(is_wp_error($integrity)){return $integrity;}$scheduled=self::schedule();if(is_wp_error($scheduled)){return$scheduled;}update_option(self::VERSION_OPTION,GCU_VERSION,false);update_option(self::SCHEMA_OPTION,GCU_SCHEMA_VERSION,false);delete_option(self::UPGRADE_ERROR);if($activation){update_option('gcu_enabled',1,false);}flush_rewrite_rules();return true;}finally{self::release_lock();}}
