	public static function rollback_options(){return self::rollback_snapshot();}
	public static function rollback_snapshot(){global$wpdb;if(!self::acquire_lock()){return new WP_Error('gcu_rollback_locked',__('A File 14 install, upgrade or recovery operation is already running.','global-clinic-usp-integration'));}try{$s=get_option(self::SNAPSHOT_OPTION,array());if(empty($s['snapshot_hash'])||!isset($s['options'],$s['tables'])){return new WP_Error('gcu_no_snapshot',__('No verified rollback snapshot is available.','global-clinic-usp-integration'));}$copy=$s;$hash=(string)$copy['snapshot_hash'];unset($copy['snapshot_hash']);$enc=wp_json_encode($copy);if(false===$enc||!hash_equals($hash,hash('sha256',$enc))){return new WP_Error('gcu_snapshot_integrity_failed',__('The File 14 rollback snapshot failed integrity verification.','global-clinic-usp-integration'));}$v=self::verify_schema();if(is_wp_error($v)){return $v;}if(isset($s['tables']['future_records'])||isset($s['tables']['future_reports'])){$fv=class_exists('GCU_Future_Intelligence')?GCU_Future_Intelligence::verify_schema():new WP_Error('gcu_future_schema_unavailable',__('Future schema verifier is unavailable.','global-clinic-usp-integration'));if(is_wp_error($fv)){return $fv;}}$base=self::tables();$maps=array('claim_history'=>$base['claim_history'],'claims'=>$base['claims'],'blocks'=>$base['blocks'],'placements'=>$base['placements'],'experiments'=>$base['experiments']);if(class_exists('GCU_Future_Intelligence')){$ft=GCU_Future_Intelligence::tables();$maps['future_records']=$ft['records'];$maps['future_reports']=$ft['reports'];}if(false===$wpdb->query('START TRANSACTION')){return new WP_Error('gcu_rollback_transaction_failed',__('Rollback transaction could not start.','global-clinic-usp-integration'));}try{$captured_at=gmdate('Y-m-d H:i:s',isset($s['captured_at'])?(int)$s['captured_at']:0);foreach($maps as$k=>$table){if(!array_key_exists($k,$s['tables'])){continue;}foreach(is_array($s['tables'][$k])?$s['tables'][$k]:array()as$row){if(!is_array($row)||empty($row['id'])){throw new RuntimeException('invalid-'.$k);}$current=$wpdb->get_row($wpdb->prepare("SELECT * FROM `$table` WHERE id=%d",(int)$row['id']),ARRAY_A);if($current){$changed_at=!empty($current['updated_at'])?$current['updated_at']:(isset($current['created_at'])?$current['created_at']:'');if($captured_at&&$changed_at&&strtotime($changed_at.' UTC')>strtotime($captured_at.' UTC')){continue;}$ok=$wpdb->replace($table,$row);if(false===$ok){throw new RuntimeException('replace-'.$k);}}else{$ok=$wpdb->insert($table,$row);if(false===$ok){throw new RuntimeException('insert-'.$k);}}}}if(false===$wpdb->query('COMMIT')){throw new RuntimeException('commit');}}catch(Exception$e){$wpdb->query('ROLLBACK');return new WP_Error('gcu_rollback_write_failed',__('File 14 rollback could not be completed atomically.','global-clinic-usp-integration'));}foreach($s['options']as$n=>$entry){if(empty($entry['exists'])){delete_option($n);}else{update_option($n,$entry['value'],false);}}return true;}finally{self::release_lock();}}
	public static function schedule(){foreach(array(array('gcu_daily_governance_check',time()+HOUR_IN_SECONDS,'daily'),array('gcu_process_outbox',time()+300,'gcu_five_minutes'),array('gcu_process_inbox',time()+330,'gcu_five_minutes'),array('gcu_lifecycle_cleanup',time()+HOUR_IN_SECONDS,'hourly'))as$job){if(wp_next_scheduled($job[0])){continue;}$r=wp_schedule_event($job[1],$job[2],$job[0],array(),true);if(is_wp_error($r)||false===$r){$code=is_wp_error($r)?$r->get_error_code():'schedule_failed';GCU_Observability::log('error','cron_schedule_failed',array('hook'=>$job[0],'code'=>$code));return new WP_Error('gcu_cron_schedule_failed',__('File 14 could not schedule a required governance or delivery job.','global-clinic-usp-integration'),array('hook'=>$job[0],'code'=>$code));}}return true;}
	private static function install_lock_active(){global$wpdb;$state=get_option(self::LOCK_OPTION,false);if(!$state){return false;}$at=is_array($state)&&!empty($state['acquired_at'])?(int)$state['acquired_at']:0;if($at&&$at>time()-600){return true;}$name=substr($wpdb->prefix.'gcu-install-upgrade',0,64);$wpdb->last_error='';$used=$wpdb->get_var($wpdb->prepare('SELECT IS_USED_LOCK(%s)',$name));if(''!==(string)$wpdb->last_error){GCU_Observability::log('error','install_lock_probe_failed',array('age'=>$at?max(0,time()-$at):null));return true;}if(null===$used||false===$used||0===(int)$used){delete_option(self::LOCK_OPTION);GCU_Observability::log('warning','stale_install_lock_recovered',array('age'=>$at?max(0,time()-$at):null));return false;}return true;}
	private static function acquire_lock(){global$wpdb;$name=substr($wpdb->prefix.'gcu-install-upgrade',0,64);$locked=(int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s, 1)',$name));if(1!==$locked){return false;}self::$db_lock=$name;update_option(self::LOCK_OPTION,array('acquired_at'=>time(),'request'=>GCU_Policy::trace_id()),false);return true;}
	private static function release_lock(){global$wpdb;if(self::$db_lock){$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',self::$db_lock));self::$db_lock=false;}delete_option(self::LOCK_OPTION);}
	private static function safe_error_record(WP_Error$e){return array('code'=>sanitize_key($e->get_error_code()),'occurred_at'=>time(),'version'=>GCU_VERSION,'schema'=>GCU_SCHEMA_VERSION);}
